import { expect, test } from "bun:test";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { config, writeConfig } from "../src/ssh.ts";

test("config and its file", () => {
  const peers = [
    { host: "torus", ip: "100.64.0.1" },
    { host: "v6only", ip: "fd7a::1" },
    { host: "razer", ip: "100.64.0.2" },
  ];
  const want =
    "# auto-generated by the frontend, do not edit, changes are overwritten\n\nHost torus\n\tHostName 100.64.0.1\n\nHost razer\n\tHostName 100.64.0.2\n";
  expect(config(peers)).toBe(want);
  const file = join(mkdtempSync(join(tmpdir(), "phos-ssh-")), "ssh_config");
  writeConfig(file, peers);
  expect(readFileSync(file, "utf8")).toBe(want);
  writeConfig(file, peers.slice(0, 1));
  expect(readFileSync(file, "utf8")).toBe(want.split("\nHost razer")[0]);
});
